CREATE OR REPLACE FUNCTION public.can_access_conversation(p_conversation_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public SET row_security = off AS $$ SELECT EXISTS (SELECT 1 FROM public.chat_participants WHERE conversation_id = p_conversation_id AND user_id = auth.uid()) OR EXISTS (SELECT 1 FROM public.organization_admins oa JOIN public.profiles p ON p.organization_id = oa.organization_id JOIN public.chat_participants cp ON cp.user_id = p.id WHERE oa.user_id = auth.uid() AND cp.conversation_id = p_conversation_id) OR EXISTS (SELECT 1 FROM public.organization_admins oa JOIN public.profiles tutor_p ON tutor_p.organization_id = oa.organization_id JOIN public.students s ON s.tutor_id = tutor_p.id JOIN public.chat_participants cp ON cp.user_id = s.linked_user_id WHERE oa.user_id = auth.uid() AND cp.conversation_id = p_conversation_id) OR EXISTS (SELECT 1 FROM public.chat_participants cp JOIN public.students s ON s.linked_user_id = cp.user_id WHERE cp.conversation_id = p_conversation_id AND public.parent_can_access_student(s.id)); $$; REVOKE ALL ON FUNCTION public.can_access_conversation(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_access_conversation(uuid) TO authenticated, service_role;;
